#!/usr/bin/env node

/**
 * docs-route-scanner.mjs
 *
 * Reads Angular routing files from the Dino application (`dinoapp`) and builds a canonical route map.
 * The map is the single source of truth for what documentation pages should exist.
 *
 * Convention-based: section/slug/title are auto-derived from routing paths.
 * Only genuine exceptions need entries in DOC_OVERRIDES.
 *
 * Screenshot configs are auto-generated by scanning component templates for
 * interactive UI patterns (TEMPLATE_PATTERNS).
 *
 * Parameterised routes (e.g. :form_schema_id) are auto-detected and configured
 * with `resolveFrom` so Cypress can discover the ID at runtime.  No manual
 * ROUTE_FIXUPS are needed for nested parameterised segments.
 *
 * Output shape:
 * {
 *   'forms/index': {
 *     docFile: 'docs/forms/index.md',
 *     url: '/forms',
 *     moduleDir: 'mat-forms',
 *     componentFiles: ['projects/dinoapp/src/mat-forms/forms-e2e.component.ts', ...]
 *   },
 *   ...
 * }
 */

import fs from 'fs';
import path from 'path';
import {fileURLToPath} from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// This script lives under `dino-doc/scripts/` but it needs to scan the Dino
// application sources from the repository root.
const DOC_ROOT = path.resolve(__dirname, '..');
const REPO_ROOT = path.resolve(DOC_ROOT, '..');

const APP_SRC = path.join(REPO_ROOT, 'projects', 'dinoapp', 'src');
const APP_APP_DIR = path.join(APP_SRC, 'app');
const ROOT_ROUTING = path.join(APP_APP_DIR, 'dino-routing.module.ts');

function absFromDocRoot(p) {
  return path.isAbsolute(p) ? p : path.join(DOC_ROOT, p);
}

/**
 * Overrides for modules that don't follow auto-derivation conventions.
 * Only needed for: shared doc pages, non-standard section mapping.
 * Unspecified fields (section, slug) fall back to autoDerive().
 *
 * When to add an override:
 * - Module name doesn't match its doc section (e.g. mat-main → interface)
 * - Multiple modules share one doc page (e.g. mat-cases + mat-locations → areas)
 * - A child list view should merge into the parent index page
 *
 * Everything else is auto-derived from routing paths — no manual config needed.
 */
const DOC_OVERRIDES = {
  // App shell: route path is '' but we want it under the Interface section
  'main-nav':               { section: 'interface', slug: 'index' },

  // Shared doc pages: same screen in create/edit mode → one doc
  'create-form':            { slug: 'edit-form' },
  'create-report':          { slug: 'edit-report' },

  // Metric value types: each is its own page under the Metrics section so all
  // metric types are documented individually. cases/locations/organizations/
  // projects are auto-derived correctly from their module dir (→ metrics/cases,
  // metrics/locations, …); only Thematic Areas needs an override, to keep the
  // existing 'areas' slug (preserves its screenshots and the metrics/areas-edit
  // EXTRA_ROUTE_ENTRIES) while giving it a friendly title.
  'areas':                  { slug: 'areas', title: 'Thematic Areas' },

  // List views: merge into the section index page
  'forms-list':             { slug: 'index' },
  'reports-list':           { slug: 'index' },

  // Import data wizard: its own page under Forms (route forms/:id/import).
  // Without this it would auto-derive the ugly slug 'import-form-page'.
  'import-form-page':       { slug: 'import', title: 'Import Data' },

  // Friendlier slug for the users management list
  'users-list':             { slug: 'users-list' },

  // Single-route section that should be an index page
  'edit-public-form':       { slug: 'index' },
};

/**
 * Maps route path prefixes that don't match their doc section name.
 */
const SECTION_ALIASES = {
  'login':          'getting-started',
  'reset-password': 'getting-started',
  'users':          'administration',
  'languages':      'administration',
  'f':              'public-forms',
};

/**
 * Schema editor fixups — these modules load at a parent URL (e.g. /forms/schema)
 * but for documentation we want to show an EXISTING schema with fields populated.
 * The module's internal routing has a :id/edit child we can't auto-detect from
 * the parent routing file alone.
 *
 * These are the ONLY manual fixups; all parameterised-route fixups are automatic.
 */
/**
 * Extra route entries for screenshots that require intermediate navigation
 * not covered by auto-detection.  These are features on sub-pages (e.g. the
 * export button on the data list, reached only after clicking a grid tile).
 *
 * WHEN TO ADD AN ENTRY:
 * - The feature lives on a sub-page that requires clicking through parent UI
 *   (e.g. selecting a grid tile to reach a data list, then expanding a panel)
 * - The UI pattern is NOT detectable from routing or template scanning alone
 *   because it depends on runtime navigation state
 *
 * HOW TO ADD AN ENTRY:
 *   {
 *     url:         '/section/{schemaId}',          // URL with {param} placeholders
 *     dir:         'section',                      // doc section for the screenshot directory
 *     resolveFrom: '/section',                     // list page where Cypress picks up the ID
 *     screenshots: [{
 *       name:  'section/slug-suffix',              // screenshot filename (section/slug + descriptive suffix)
 *       setup: "cy.get('selector')...;",           // Cypress commands to reach the UI state
 *     }],
 *   }
 *
 * The `resolveFrom` URL tells Cypress where to navigate first to discover the
 * runtime ID that replaces {schemaId}.  The `setup` string is raw Cypress
 * commands injected into the test to reach the desired screenshot state.
 */
