/**
 * Recursively resolve <dino-*> tags to library component templates.
 * Follows the convention: <dino-{name}> → projects/material/{name}/src/{name}.html
 *
 * Resolves up to `maxDepth` levels deep to catch patterns nested inside library
 * components (e.g. component → <dino-collect> → <dino-search-filters-bar> → <dino-export-button>).
 * A visited set prevents infinite loops from circular references.
 *
 * @param {string} htmlContent - HTML content to scan for <dino-*> tags
 * @param {number} [depth=0] - Current recursion depth
 * @param {Set<string>} [visited=new Set()] - Already-resolved library paths
 * @param {number} [maxDepth=3] - Maximum resolution depth
 * @returns {string[]} Array of resolved HTML contents
 */
function resolveLibraryTemplates(htmlContent, depth = 0, visited = new Set(), maxDepth = 3) {
  const resolved = [];
  if (depth >= maxDepth) return resolved;

  for (const [, name] of htmlContent.matchAll(/<dino-([\w-]+)/g)) {
    const libPath = path.join(REPO_ROOT, 'projects', 'material', name, 'src', `${name}.html`);
    if (visited.has(libPath) || !fs.existsSync(libPath)) continue;
    visited.add(libPath);
    const content = fs.readFileSync(libPath, 'utf8');
    resolved.push(content);
    resolved.push(...resolveLibraryTemplates(content, depth + 1, visited, maxDepth));
  }
  return resolved;
}

/**
 * Scan component HTML files + resolved library templates against TEMPLATE_PATTERNS.
 * Returns an array of extra screenshot configs for the given route.
 *
 * Library resolution convention: <dino-{name}> → projects/material/{name}/src/{name}.html
 * Resolution is recursive up to depth 3 (see resolveLibraryTemplates).
 *
 * @param {string[]} componentFiles - List of component file paths
 * @param {string} baseName - Base screenshot name (e.g. 'forms/index')
 * @returns {{ name: string, setup: string }[]}
 */
function scanTemplatesForScreenshots(componentFiles, baseName) {
  const htmlContents = [];
  const visited = new Set();

  for (const f of componentFiles.filter(f => f.endsWith('.html'))) {
    if (!fs.existsSync(f)) continue;
    const content = fs.readFileSync(f, 'utf8');
    htmlContents.push(content);

    // Recursively resolve dino-* tags to library component templates (up to depth 3)
    htmlContents.push(...resolveLibraryTemplates(content, 0, visited));
  }

  const allHtml = htmlContents.join('\n');
  const screenshots = [];

  for (const pattern of TEMPLATE_PATTERNS) {
    if (pattern.match.test(allHtml)) {
      const entry = {
        name: `${baseName}${pattern.suffix}`,
        setup: pattern.setup,
        selector: pattern.selector,
        description: pattern.description,
      };
      if (pattern.viewport) entry.viewport = pattern.viewport;
      screenshots.push(entry);
    }
  }

  return screenshots;
}

// ---------------------------------------------------------------------------
// Route parsing — understands nested children: [...] blocks
// ---------------------------------------------------------------------------

/**
 * Parse loadChildren entries from a routing file, including routes nested
 * under `children: [...]` blocks.  Returns array of { path, moduleDir }.
 *
 * This handles:
 *   { path: 'x', loadChildren: () => import('./mod/...') }          — direct
 *   { path: ':id', children: [ { path: 'y', loadChildren: ... } ] } — nested
 */
function parseLoadChildren(fileContent) {
  // Find the routes array
  const routesStart = fileContent.search(/(?:const|let)\s+routes[\s:]/);
  if (routesStart === -1) {
    // Fallback: try the flat regex approach for files without a routes variable
    return parseLoadChildrenFlat(fileContent);
  }

  const arrayStart = fileContent.indexOf('[', routesStart);
  if (arrayStart === -1) return [];

  const entries = [];
  parseRouteBlock(fileContent, arrayStart, '', entries);
  return entries;
}

/**
 * Recursively parse a route array block, extracting path + import pairs.
 * Handles nested `children` arrays by prepending the parent path.
 */
function parseRouteBlock(content, startIdx, parentPath, entries) {
  const inner = extractBracketContent(content, startIdx, '[', ']');
  if (!inner) return;

  const objects = splitTopLevelObjects(inner);

  for (const obj of objects) {
    const pathMatch = obj.match(/path:\s*'([^']*)'/);
    if (!pathMatch) continue;

    const routePath = pathMatch[1];
    const fullPath = joinPaths(parentPath, routePath);

    // Check for loadChildren import (both ./ and ../ patterns)
    const importMatch = obj.match(/import\(\s*'(?:\.\/|\.\.\/)([\w-]+)/);
    if (importMatch) {
      entries.push({ path: fullPath, moduleDir: importMatch[1] });
    }

    // Check for nested children: [...]
    const childrenIdx = obj.search(/children:\s*\[/);
    if (childrenIdx !== -1) {
      const bracketStart = obj.indexOf('[', childrenIdx);
      parseRouteBlock(obj, bracketStart, fullPath, entries);
    }
  }
}

/**
 * Fallback flat regex parser for files that don't follow the standard pattern.
 */
function parseLoadChildrenFlat(fileContent) {
  const entries = [];
  const re = /path:\s*'([^']*)'[\s\S]*?import\(\s*'(?:\.\/|\.\.\/)([\w-]+)/g;
  let match;
  while ((match = re.exec(fileContent)) !== null) {
    entries.push({ path: match[1], moduleDir: match[2] });
  }
  return entries;
}

function joinPaths(parent, child) {
  if (!parent) return child;
  if (!child) return parent;
  return `${parent}/${child}`;
}

/**
 * Extract content within matching brackets starting at startIdx.
 * Skips over string literals and nested bracket pairs.
 */
function extractBracketContent(text, startIdx, open, close) {
  if (text[startIdx] !== open) return null;

  let depth = 1;
  let i = startIdx + 1;

  while (i < text.length && depth > 0) {
    const ch = text[i];
    if (ch === open) depth++;
    else if (ch === close) depth--;
    else if (ch === "'" || ch === '"' || ch === '`') {
      // Skip string literals
      const quote = ch;
      i++;
      while (i < text.length && text[i] !== quote) {
        if (text[i] === '\\') i++;
        i++;
      }
    }
    i++;
  }

  return text.substring(startIdx + 1, i - 1);
}

/**
 * Split content into top-level { ... } objects, respecting nesting.
 */
function splitTopLevelObjects(content) {
  const objects = [];
  let depth = 0;
  let start = -1;

  for (let i = 0; i < content.length; i++) {
    const ch = content[i];
    if (ch === '{') {
      if (depth === 0) start = i;
      depth++;
    } else if (ch === '}') {
      depth--;
      if (depth === 0 && start !== -1) {
        objects.push(content.substring(start, i + 1));
        start = -1;
      }
    } else if (ch === "'" || ch === '"' || ch === '`') {
      const quote = ch;
      i++;
      while (i < content.length && content[i] !== quote) {
        if (content[i] === '\\') i++;
        i++;
      }
    }
  }

  return objects;
}

// ---------------------------------------------------------------------------
// Route map building
// ---------------------------------------------------------------------------

/**
 * Find all component-related files in a module directory (TS + HTML, excluding specs).
 */
function findComponentFiles(moduleDir) {
  const dirPath = path.join(APP_APP_DIR, moduleDir);
  if (!fs.existsSync(dirPath)) return [];

  return fs.readdirSync(dirPath)
    .filter(f => (f.endsWith('.ts') || f.endsWith('.html')) && !f.endsWith('.spec.ts'))
    .map(f => path.join(APP_APP_DIR, moduleDir, f));
}

/**
 * Recursively list .ts/.html source files under a directory, excluding specs.
 */
function walkSourceFiles(dirPath) {
  if (!fs.existsSync(dirPath)) return [];
  const out = [];
  for (const entry of fs.readdirSync(dirPath, {withFileTypes: true})) {
    const full = path.join(dirPath, entry.name);
    if (entry.isDirectory()) {
      out.push(...walkSourceFiles(full));
    } else if (
      (entry.name.endsWith('.ts') || entry.name.endsWith('.html')) &&
      !entry.name.endsWith('.spec.ts')
    ) {
      out.push(full);
    }
  }
  return out;
}

/**
 * Resolve <dino-*> tags found in HTML to their library component template PATHS.
 * Convention: <dino-{name}> → projects/material/{name}/src/{name}.html
 * Recurses up to maxDepth to follow tags nested inside library templates.
 *
 * Sibling of resolveLibraryTemplates (which returns CONTENTS for screenshot
 * scanning); this returns PATHS so they can be fed to the doc generator.
 */
function resolveLibraryComponentFiles(htmlContent, depth = 0, visited = new Set(), maxDepth = 3) {
  const out = [];
  if (depth >= maxDepth) return out;
  for (const [, name] of htmlContent.matchAll(/<dino-([\w-]+)/g)) {
    const libPath = path.join(REPO_ROOT, 'projects', 'material', name, 'src', `${name}.html`);
    if (visited.has(libPath) || !fs.existsSync(libPath)) continue;
    visited.add(libPath);
    out.push(libPath);
    out.push(...resolveLibraryComponentFiles(fs.readFileSync(libPath, 'utf8'), depth + 1, visited, maxDepth));
  }
  return out;
}

/**
 * Augment a list of source files with the HTML templates of any <dino-*>
 * library components they reference.  The dinoapp module files are thin
 * wrappers (module/routing/conf + a container template that just embeds
 * <dino-...>); the ACTUAL user-facing UI — field labels, action buttons,
 * dialogs — lives in those library templates, so the doc generator needs them.
 */
function withLibrarySources(files) {
  const visited = new Set();
  const libs = [];
  for (const f of files.filter(f => f.endsWith('.html') && fs.existsSync(f))) {
    libs.push(...resolveLibraryComponentFiles(fs.readFileSync(f, 'utf8'), 0, visited));
  }
  return [...files, ...libs];
}

/**
 * Collect the source files used to GENERATE documentation for a module.
 * Unlike findComponentFiles (shallow, feeds the screenshot scanner), this
 * walks the module recursively (to reach components/*.component.html) and
 * resolves referenced <dino-*> library templates.
 */
function findDocSourceFiles(moduleDir) {
  return withLibrarySources(walkSourceFiles(path.join(APP_APP_DIR, moduleDir)));
}

/**
 * Scan all routing files and build the complete route map.
 */
export function scanRoutes() {
  const routeMap = {};

  if (!fs.existsSync(ROOT_ROUTING)) {
    console.error(`Root routing file not found: ${ROOT_ROUTING}`);
    return routeMap;
  }

  // App shell (mat-main) is not lazy-loaded so it won't be found by parseLoadChildren.
  // Add it manually — it documents the toolbar, side navigation, and user area.
  processModule('', 'main-nav', routeMap, [
    path.join(REPO_ROOT, 'projects', 'material', 'main-nav', 'src', 'main-nav.ts'),
    path.join(REPO_ROOT, 'projects', 'material', 'main-nav', 'src', 'main-nav.html'),
  ]);

  const rootContent = fs.readFileSync(ROOT_ROUTING, 'utf8');
  const rootEntries = parseLoadChildren(rootContent);

  for (const root of rootEntries) {
    processModule(root.path, root.moduleDir, routeMap);

    // Check if the module has its own child routing file
    const childRoutingFile = findRoutingFile(root.moduleDir);
    if (childRoutingFile) {
      const childContent = fs.readFileSync(childRoutingFile, 'utf8');
      const childEntries = parseLoadChildren(childContent);

      for (const child of childEntries) {
        const fullPath = root.path ? `${root.path}/${child.path}` : child.path;
        processModule(fullPath, child.moduleDir, routeMap);
      }
    }
  }

  return routeMap;
}

/**
 * Find the routing file for a given module directory.
 */
function findRoutingFile(moduleDir) {
  const dirPath = path.join(APP_APP_DIR, moduleDir);
  if (!fs.existsSync(dirPath)) return null;

  const files = fs.readdirSync(dirPath);
  const routingFile = files.find(f => f.includes('-routing.module.ts'));
  return routingFile ? path.join(dirPath, routingFile) : null;
}

/**
 * Process a single module entry and add it to the route map.
 * Auto-derives section/slug/title, then applies overrides for exceptions.
 * @param {string[]} [extraFiles] - Additional source files to include (e.g. library components).
 */
function processModule(routePath, moduleDir, routeMap, extraFiles = []) {
  // Auto-derive base mapping, then apply overrides
  const auto = autoDerive(routePath, moduleDir);
  const override = DOC_OVERRIDES[moduleDir] || {};
  const docMapping = { ...auto, ...override };

  if (override.section || override.slug) {
    console.log(`  [override] ${moduleDir} → ${docMapping.section}/${docMapping.slug}`);
  }

  const key = `${docMapping.section}/${docMapping.slug}`;

  if (DOC_EXCLUDES.has(key)) {
    console.log(`  [excluded] ${moduleDir} → ${key} (not documented)`);
    return;
  }

  // If the key already exists, merge component files (multiple modules can map to the same doc)
  if (routeMap[key]) {
    const newFiles = [...findComponentFiles(moduleDir), ...extraFiles];
    for (const f of newFiles) {
      if (!routeMap[key].componentFiles.includes(f)) {
        routeMap[key].componentFiles.push(f);
      }
    }
    const newDocFiles = [...findDocSourceFiles(moduleDir), ...withLibrarySources(extraFiles)];
    for (const f of newDocFiles) {
      if (!routeMap[key].docSourceFiles.includes(f)) {
        routeMap[key].docSourceFiles.push(f);
      }
    }
    // Also track additional module dirs
    if (!routeMap[key].moduleDirs.includes(moduleDir)) {
      routeMap[key].moduleDirs.push(moduleDir);
    }
    return;
  }

  routeMap[key] = {
    docFile: `docs/en/${docMapping.section}/${docMapping.slug}.md`,
    url: routePath ? `/${routePath}` : '/',
    title: docMapping.title,
    section: docMapping.section,
    moduleDir,
    moduleDirs: [moduleDir],
    componentFiles: [...findComponentFiles(moduleDir), ...extraFiles],
    docSourceFiles: [...new Set([...findDocSourceFiles(moduleDir), ...withLibrarySources(extraFiles)])],
  };
}

/**
 * Export the route map as a JSON file suitable for Cypress consumption.
 *
 * Parameterised routes (URLs containing :param) are auto-configured:
 *   - resolveFrom: the section's list page (URL prefix before the :param)
 *   - url: template with {schemaId} replacing the :param segment
 *
 * SCHEMA_EDITOR_FIXUPS handle the one case that can't be auto-detected:
 * schema editors that need an existing entity loaded via an internal :id/edit route.
 */
export function exportRouteMapForCypress(routeMap) {
  const entries = Object.entries(routeMap)
    .filter(([key]) => !SCREENSHOT_EXCLUDES.has(key))
    .map(([key, r]) => {
      const baseName = `${r.section}/${path.basename(r.docFile, '.md')}`;
      const screenshots = [
        { name: baseName, setup: null, description: `Main view of the ${r.title} page` },
        ...scanTemplatesForScreenshots(r.componentFiles, baseName),
      ];

      const entry = { url: r.url, dir: r.section, screenshots };

      // --- Schema editor fixups (manual — internal :id/edit not auto-detectable) ---
      const fixup = SCHEMA_EDITOR_FIXUPS[key];
      if (fixup) {
        entry.url = fixup.urlTemplate;
        entry.resolveFrom = fixup.resolveFrom;
        if (fixup.resolveAction) entry.resolveAction = fixup.resolveAction;
        return entry;
      }

      // --- Auto-detect parameterised routes ---
      if (r.url.includes(':')) {
        const segments = r.url.split('/');
        const paramIdx = segments.findIndex(s => s.startsWith(':'));

        // resolveFrom = URL prefix before the parameterised segment
        const resolveFrom = segments.slice(0, paramIdx).join('/') || '/';
        // urlTemplate = replace :param with {schemaId}
        const urlTemplate = segments.map(s => s.startsWith(':') ? '{schemaId}' : s).join('/');

        entry.resolveFrom = resolveFrom;
        entry.url = urlTemplate;
      }

      return entry;
    });

  // Append manual entries for features on sub-pages
  entries.push(...EXTRA_ROUTE_ENTRIES);

  fs.writeFileSync(
    absFromDocRoot('scripts/docs-route-map.json'),
    JSON.stringify(entries, null, 2) + '\n',
  );

  return entries;
}

// CLI entry point
if (process.argv[1] && process.argv[1].endsWith('docs-route-scanner.mjs')) {
  const routeMap = scanRoutes();
  console.log(`Scanned ${Object.keys(routeMap).length} doc-mapped routes:`);
  for (const [key, val] of Object.entries(routeMap)) {
    console.log(`  ${key} → ${val.url} (${val.componentFiles.length} files)`);
  }

  const cypressEntries = exportRouteMapForCypress(routeMap);
  console.log('\nRoute map exported to scripts/docs-route-map.json');

  // Show template-detected screenshots
  for (const entry of cypressEntries) {
    if (entry.screenshots.length > 1) {
      const extras = entry.screenshots.slice(1).map(s => s.name.split('/').pop()).join(', ');
      console.log(`  ${entry.url} → extra screenshots: ${extras}`);
    }
    if (entry.resolveFrom) {
      console.log(`  ${entry.url} → resolveFrom: ${entry.resolveFrom} (auto-detected)`);
    }
  }

  // --- Diagnostic Summary ---
  const withInteractive = cypressEntries.filter(e => e.screenshots.length > 1).length;
  console.log('\n--- Diagnostic Summary ---');
  console.log(`Routes: ${cypressEntries.length} total, ${withInteractive} with interactive screenshots`);
  console.log(`Manual entries: ${EXTRA_ROUTE_ENTRIES.length} (EXTRA_ROUTE_ENTRIES)`);
  console.log(`Excluded from screenshots: ${SCREENSHOT_EXCLUDES.size} (SCREENSHOT_EXCLUDES)`);

  // Report TEMPLATE_PATTERNS that matched 0 routes
  let unmatchedPatterns = 0;
  for (const p of TEMPLATE_PATTERNS) {
    const matchCount = cypressEntries.filter(e =>
      e.screenshots.some(s => s.selector === p.selector),
    ).length;
    if (matchCount === 0) {
      console.warn(`  WARN: Pattern "${p.description}" (${p.suffix}) matched 0 routes`);
      unmatchedPatterns++;
    }
  }
  if (unmatchedPatterns === 0) {
    console.log('Template patterns: all matched at least 1 route');
  }

  // Report unresolved <dino-*> tags across all scanned component HTML files
  const allComponentFiles = Object.values(routeMap).flatMap(r => r.componentFiles);
  const unresolvedTags = new Set();
  for (const f of allComponentFiles.filter(f => f.endsWith('.html'))) {
    if (!fs.existsSync(f)) continue;
    const content = fs.readFileSync(f, 'utf8');
    for (const [, name] of content.matchAll(/<dino-([\w-]+)/g)) {
      const libPath = path.join(REPO_ROOT, 'projects', 'material', name, 'src', `${name}.html`);
      if (!fs.existsSync(libPath)) {
        unresolvedTags.add(`<dino-${name}>`);
      }
    }
  }
  if (unresolvedTags.size > 0) {
    console.warn(`Unresolved <dino-*> tags (${unresolvedTags.size} — no matching library template):`);
    for (const tag of [...unresolvedTags].sort()) {
      console.warn(`  ${tag}`);
    }
  } else {
    console.log('Library tags: all <dino-*> tags resolved');
  }
}
